def _generate_expression(self):
    # turn my _format attribute into the _expression attribute
    e = []
    for part in PARSE_RE.split(self._format):
        if not part:
            continue
        elif part == '{{':
            e.append(r'\{')
        elif part == '}}':
            e.append(r'\}')
        elif part[0] == '{':
            # Must be fully enclosed in matching braces
            if not part.endswith('}'):
                raise ValueError(
                    "format string %r has an unclosed brace at position %d" %
                    (self._format, self._format.index(part)))
            # this will be a braces-delimited field to handle
            e.append(self._handle_field(part))
        else:
            # Text without braces - check for unmatched braces
            if '{' in part or '}' in part:
                raise ValueError(
                    "format string %r has malformed brace structure" %
                    self._format)
            # just some text to match
            e.append(REGEX_SAFETY.sub(self._regex_replace, part))
    return ''.join(e)
